try (Workbook workbook = new XSSFWorkbook()) {
    Sheet sheet = workbook.createSheet("Pracownicy");
    String[] headers = {"Imie", "Stanowisko", "Data", "Pensja"};
    Row headerRow = sheet.createRow(0);
    for (int col = 0; col < headers.length; col++) {
        headerRow.createCell(col).setCellValue(headers[col]);
    }
    // ... wiersze danych ...
    Row totalRow = sheet.createRow(6);
    totalRow.createCell(0).setCellValue("RAZEM");
    Cell formulaCell = totalRow.createCell(3);
    formulaCell.setCellFormula("SUM(D2:D6)");

    FormulaEvaluator evaluator = workbook.getCreationHelper().createFormulaEvaluator();
    double total = evaluator.evaluate(formulaCell).getNumberValue();

    Path outputFile = Files.createTempDirectory("poi_demo").resolve("pracownicy.xlsx");
    try (FileOutputStream fileOut = new FileOutputStream(outputFile.toFile())) {
        workbook.write(fileOut);
    }
}
